        # [doc = " Generate random invocation fixtures from rules"] fn invocation_fixtures (rules : & FxHashMap < String , DeclarativeMacro > ,) -> Vec < (String , tt :: TopSubtree < Span >) > { let mut seed = 123456789 ; let mut res = Vec :: new () ; for (name , it) in rules . iter () . sorted_by_key (| & (id , _) | id) { for rule in it . rules . iter () { for _ in 0 .. 2 { let mut try_cnt = 0 ; loop { let mut builder = tt :: TopSubtreeBuilder :: new (tt :: Delimiter { open : DUMMY , close : DUMMY , kind : tt :: DelimiterKind :: Invisible , }) ; for op in rule . lhs . iter () { collect_from_op (op , & mut builder , & mut seed) ; } let subtree = builder . build () ; if it . expand (& subtree , | _ | () , DUMMY , Edition :: CURRENT) . err . is_none () { res . push ((name . clone () , subtree)) ; break ; } try_cnt += 1 ; if try_cnt > 100 { panic ! ("invocation fixture {name} cannot be generated.\n") ; } } } } } return res ; fn collect_from_op (op : & Op , builder : & mut tt :: TopSubtreeBuilder < Span > , seed : & mut usize) { return match op { Op :: Var { kind , .. } => match kind . as_ref () { Some (MetaVarKind :: Ident) => builder . push (make_ident ("foo")) , Some (MetaVarKind :: Ty) => builder . push (make_ident ("Foo")) , Some (MetaVarKind :: Tt) => builder . push (make_ident ("foo")) , Some (MetaVarKind :: Vis) => builder . push (make_ident ("pub")) , Some (MetaVarKind :: Pat) => builder . push (make_ident ("foo")) , Some (MetaVarKind :: Path) => builder . push (make_ident ("foo")) , Some (MetaVarKind :: Literal) => builder . push (make_literal ("1")) , Some (MetaVarKind :: Expr (_)) => builder . push (make_ident ("foo")) , Some (MetaVarKind :: Lifetime) => { builder . push (make_punct ('\'')) ; builder . push (make_ident ("a")) ; } Some (MetaVarKind :: Block) => make_subtree (tt :: DelimiterKind :: Brace , builder) , Some (MetaVarKind :: Item) => { builder . push (make_ident ("fn")) ; builder . push (make_ident ("foo")) ; make_subtree (tt :: DelimiterKind :: Parenthesis , builder) ; make_subtree (tt :: DelimiterKind :: Brace , builder) ; } Some (MetaVarKind :: Meta) => { builder . push (make_ident ("foo")) ; make_subtree (tt :: DelimiterKind :: Parenthesis , builder) ; } None => () , Some (kind) => panic ! ("Unhandled kind {kind:?}") , } , Op :: Literal (it) => builder . push (tt :: Leaf :: from (it . clone ())) , Op :: Ident (it) => builder . push (tt :: Leaf :: from (it . clone ())) , Op :: Punct (puncts) => { for punct in puncts . as_slice () { builder . push (tt :: Leaf :: from (* punct)) ; } } Op :: Repeat { tokens , kind , separator } => { let max = 10 ; let cnt = match kind { RepeatKind :: ZeroOrMore => rand (seed) % max , RepeatKind :: OneOrMore => 1 + rand (seed) % max , RepeatKind :: ZeroOrOne => rand (seed) % 2 , } ; for i in 0 .. cnt { for it in tokens . iter () { collect_from_op (it , builder , seed) ; } if i + 1 != cnt && let Some (sep) = separator { match & * * sep { Separator :: Literal (it) => builder . push (tt :: Leaf :: Literal (it . clone ())) , Separator :: Ident (it) => builder . push (tt :: Leaf :: Ident (it . clone ())) , Separator :: Puncts (puncts) => { for it in puncts { builder . push (tt :: Leaf :: Punct (* it)) } } Separator :: Lifetime (punct , ident) => { builder . push (tt :: Leaf :: Punct (* punct)) ; builder . push (tt :: Leaf :: Ident (ident . clone ())) ; } } ; } } } Op :: Subtree { tokens , delimiter } => { builder . open (delimiter . kind , delimiter . open) ; tokens . iter () . for_each (| it | collect_from_op (it , builder , seed)) ; builder . close (delimiter . close) ; } Op :: Ignore { .. } | Op :: Index { .. } | Op :: Count { .. } | Op :: Len { .. } | Op :: Concat { .. } => { } } ; fn rand (seed : & mut usize) -> usize { let a = 1664525 ; let c = 1013904223 ; * seed = usize :: wrapping_add (usize :: wrapping_mul (* seed , a) , c) ; * seed } fn make_ident (ident : & str) -> tt :: Leaf < Span > { tt :: Leaf :: Ident (tt :: Ident { span : DUMMY , sym : Symbol :: intern (ident) , is_raw : tt :: IdentIsRaw :: No , }) } fn make_punct (char : char) -> tt :: Leaf < Span > { tt :: Leaf :: Punct (tt :: Punct { span : DUMMY , char , spacing : tt :: Spacing :: Alone }) } fn make_literal (lit : & str) -> tt :: Leaf < Span > { tt :: Leaf :: Literal (tt :: Literal { span : DUMMY , symbol : Symbol :: intern (lit) , kind : tt :: LitKind :: Str , suffix : None , }) } fn make_subtree (kind : tt :: DelimiterKind , builder : & mut tt :: TopSubtreeBuilder < Span >) { builder . open (kind , DUMMY) ; builder . close (DUMMY) ; } } }
